export interface StudentProfile { name?:string; degree?:string; target_degree?:string; cgpa?:string; countries?:string; budget?:string; nationality?:string; language_scores?:string; intake?:string; intake_term?:string; cgpa_scale?:string; funding_need?:string; graduation?:string; github?:string; public_profiles?:string; interests?:string; career_goals?:string }
export interface Evidence { value:string; quote:string; url:string; retrieved_at:string; fetched_at?:string; note?:string; status?:'Verified'|'Verified (with note)'|'Partial'|'Unverified'|'Missing' }
export interface Opportunity { id:string; name:string; university:string; url:string; country?:string; integrity_checked?:boolean; verification?:{profile:string;attempts:Partial<Record<'funding'|'deadline'|'requirements'|'application',number>>;exhausted:boolean;updatedAt?:number}; claims:Partial<Record<'funding'|'deadline'|'requirements'|'application',Evidence|null>>; criteria?:Array<{label:string; required:string; student_value:string; status:string; evidence:Evidence|null; conversion_check?:boolean; note?:string}>; missing_information?:string[]; score?:number; recommended?:boolean; deadline_state?:string; application_step_evidence?:Evidence[]; [key:string]:unknown }
export interface Match extends Opportunity { score_components?:Record<string,number>; score_adjustment?:number }
export interface Draft { content:string; opportunityId:string; language:string; createdAt:number; blockedClaims:string[]; method:string }
export interface RunLog { id:string; status:string; stage:string; progress:number; startedAt:number; completedAt?:number; [key:string]:unknown }
export interface SharedState { id:string; profile:StudentProfile; opportunities:Opportunity[]; draft:string; run:RunLog|null; documents:Array<{id:string;name:string;text?:string;size?:number;characters?:number}>; messages:Array<{id?:string;agent:string;content:string;time?:number}>; evidence:Map<string,{url:string;text:string;retrieved_at:string;[key:string]:unknown}>; [key:string]:unknown }
